from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            comp = {(r, c)}
            seen.add((r, c))
            q = deque([(r, c)])
            while q:
                y, x = q.popleft()
                for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != bg and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        comp.add((yy, xx))
                        q.append((yy, xx))
            comps.append(comp)

    # Copy the largest connected non-background shape around each isolated marker.
    template_comp = max(comps, key=len)
    r0 = min(r for r, c in template_comp)
    r1 = max(r for r, c in template_comp)
    c0 = min(c for r, c in template_comp)
    c1 = max(c for r, c in template_comp)
    anchor_r, anchor_c = (r0 + r1) // 2, (c0 + c1) // 2
    offsets = [(r - anchor_r, c - anchor_c, grid[r][c])
               for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)]

    out = [row[:] for row in grid]
    for comp in comps:
        if comp is template_comp or len(comp) != 1:
            continue
        r, c = next(iter(comp))
        for dr, dc, color in offsets:
            y, x = r + dr, c + dc
            if 0 <= y < h and 0 <= x < w:
                out[y][x] = color
    return out

